#!/usr/bin/env python3
"""从唯一源码同步两个可独立安装的消费者技能。"""

from __future__ import annotations

import argparse
import ast
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PACKAGE = Path("consumer/ffmpeg_agent_client")
ENVFILE_SOURCE = Path("src/media_service/envfile.py")
SKILLS = ("ffmpeg-agent-connect", "ffmpeg-agent-media")
MODULES = (
    "__init__.py", "envfile.py", "cli.py", "workflow.py", "state.py",
    "errors.py", "config.py", "transport.py", "artifacts.py", "protocols.py",
)
ENTRYPOINT = b'''#!/usr/bin/env python3
"""Generated by scripts/sync-consumer-skills.py; edit consumer/ sources instead."""

import sys

if sys.version_info < (3, 10):  # noqa: UP036 -- Consumer baseline is Python 3.10.
    print('{"ok": false, "code": "PYTHON_310_REQUIRED"}')
    raise SystemExit(1)

from ffmpeg_agent_client.cli import main  # noqa: E402

if __name__ == "__main__":
    raise SystemExit(main())
'''
MANIFEST = "consumer-manifest.json"


def _sha256(content: bytes) -> str:
    return hashlib.sha256(content).hexdigest()


def _reject_symlink(path: Path) -> None:
    current = path
    while current != ROOT and ROOT in current.parents:
        if current.is_symlink():
            raise ValueError(f"refusing generated path with symlink: {current.relative_to(ROOT)}")
        current = current.parent


def _expected_files() -> dict[Path, bytes]:
    source_root = ROOT / PACKAGE
    extra = sorted(
        str(path.relative_to(source_root))
        for path in source_root.rglob("*.py")
        if path.relative_to(source_root).as_posix() not in MODULES
    )
    if extra:
        raise ValueError("unregistered client modules: " + ", ".join(extra))
    sources: dict[str, bytes] = {}
    for name in MODULES:
        source = ROOT / ENVFILE_SOURCE if name == "envfile.py" else source_root / name
        _reject_symlink(source)
        if not source.is_file():
            raise ValueError(f"missing client source: {source.relative_to(ROOT)}")
        sources[name] = source.read_bytes()
    version = None
    for node in ast.parse(sources["__init__.py"]).body:
        if isinstance(node, ast.Assign):
            if any(isinstance(target, ast.Name) and target.id == "__version__"
                   for target in node.targets):
                if isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
                    version = node.value.value
    if not version:
        raise ValueError("client __init__.py must declare a literal __version__")
    generated = {Path("media_client.py"): ENTRYPOINT}
    generated.update({Path("ffmpeg_agent_client") / name: data for name, data in sources.items()})
    manifest = {
        "schema_version": 1,
        "client_version": version,
        "generated_by": "scripts/sync-consumer-skills.py",
        "generator_sha256": _sha256(Path(__file__).read_bytes()),
        "source_root": PACKAGE.as_posix(),
        "envfile_source": ENVFILE_SOURCE.as_posix(),
        "files": {path.as_posix(): _sha256(data) for path, data in sorted(generated.items())},
    }
    generated[Path(MANIFEST)] = (json.dumps(manifest, indent=2, sort_keys=True) + "\n").encode()
    expected = {PACKAGE / "envfile.py": sources["envfile.py"]}
    for skill in SKILLS:
        scripts = Path("skills") / skill / "scripts"
        expected.update({scripts / path: content for path, content in generated.items()})
    return expected


def _unexpected_python_files(expected: dict[Path, bytes]) -> list[Path]:
    unexpected = []
    for skill in SKILLS:
        scripts = ROOT / "skills" / skill / "scripts"
        _reject_symlink(scripts)
        unexpected.extend(
            path.relative_to(ROOT) for path in scripts.rglob("*.py")
            if path.relative_to(ROOT) not in expected
        )
    return sorted(unexpected)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="只读检查同源副本、版本和 SHA-256")
    arguments = parser.parse_args()
    try:
        expected = _expected_files()
        unexpected = _unexpected_python_files(expected)
        if unexpected:
            raise ValueError("unregistered generated Python files (left untouched): "
                             + ", ".join(str(path) for path in unexpected))
        changed = []
        for relative, content in expected.items():
            target = ROOT / relative
            _reject_symlink(target)
            if target.exists() and not target.is_file():
                raise ValueError(f"generated target is not a regular file: {relative}")
            if not target.exists() or target.read_bytes() != content:
                changed.append(relative)
        if arguments.check:
            if changed:
                print("Consumer skill copies are stale: " + ", ".join(str(path) for path in changed))
                return 1
            print("Consumer skill copies and manifests are current.")
            return 0
        for relative in changed:
            target = ROOT / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(expected[relative])
        print(f"Synchronized consumer skill copies ({len(changed)} files updated).")
        return 0
    except (OSError, ValueError) as exc:
        print(f"Consumer skill synchronization failed: {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
